```javascript
const axios = require("axios");

async function getData(input) {
  try {
    const response = await axios.post(
      "https://fsave.net/proxy.php",
      "url=" + encodeURIComponent(input) + "&dt=1787152966.e5247369.a5d935f7cd554efaee7956c7d99e5965",
      {
        headers: {
          "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
          "Accept": "*/*",
          "X-Requested-With": "XMLHttpRequest"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

getData("https://www.facebook.com/share/v/1EHRaSNXih/")
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
